CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS workspaces (id uuid PRIMARY KEY, owner_id text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS documents (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), title text NOT NULL, current_version_id uuid, UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS document_versions (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, document_id uuid NOT NULL, text text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,document_id) REFERENCES documents(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS source_works (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), metadata jsonb NOT NULL, identity_status text NOT NULL DEFAULT 'unconfirmed', deleted_at timestamptz, UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS source_versions (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, work_id uuid NOT NULL, metadata jsonb NOT NULL, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,work_id) REFERENCES source_works(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS source_assets (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, version_id uuid NOT NULL, object_key text NOT NULL, filename text NOT NULL, media_type text NOT NULL, expected_bytes bigint, checksum text, status text NOT NULL DEFAULT 'pending', access text NOT NULL DEFAULT 'uploaded', eligibility text NOT NULL DEFAULT 'unknown', metadata jsonb NOT NULL DEFAULT '{}', deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,version_id) REFERENCES source_versions(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS extractions (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, asset_id uuid NOT NULL, parser_version text NOT NULL, status text NOT NULL DEFAULT 'pending', coverage jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(workspace_id,asset_id,parser_version), FOREIGN KEY(workspace_id,asset_id) REFERENCES source_assets(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS source_pages (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, extraction_id uuid NOT NULL, page_index integer NOT NULL, label text, label_status text NOT NULL, text text NOT NULL, status text NOT NULL, UNIQUE(workspace_id,id), UNIQUE(extraction_id,page_index), FOREIGN KEY(workspace_id,extraction_id) REFERENCES extractions(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS source_blocks (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, page_id uuid NOT NULL, start_offset integer NOT NULL, end_offset integer NOT NULL, coordinates jsonb, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,page_id) REFERENCES source_pages(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS source_passages (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, extraction_id uuid NOT NULL, page_id uuid NOT NULL, start_offset integer NOT NULL, end_offset integer NOT NULL, text text NOT NULL, search tsvector GENERATED ALWAYS AS (to_tsvector('english',text)) STORED, embedding vector(384), embedding_version text, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,page_id) REFERENCES source_pages(workspace_id,id) ON DELETE CASCADE, FOREIGN KEY(workspace_id,extraction_id) REFERENCES extractions(workspace_id,id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS passage_search ON source_passages USING gin(search);
CREATE INDEX IF NOT EXISTS passage_scope ON source_passages(workspace_id,extraction_id);
CREATE TABLE IF NOT EXISTS reference_imports (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), version integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'pending', original text NOT NULL, settings jsonb NOT NULL DEFAULT '{}', UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS reference_entries (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, import_id uuid NOT NULL, ordinal integer NOT NULL, original text NOT NULL, parsed jsonb NOT NULL, status text NOT NULL, candidates jsonb NOT NULL DEFAULT '[]', asset_id uuid, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,import_id) REFERENCES reference_imports(workspace_id,id) ON DELETE CASCADE, FOREIGN KEY(workspace_id,asset_id) REFERENCES source_assets(workspace_id,id) ON DELETE SET NULL (asset_id));
CREATE TABLE IF NOT EXISTS source_imports (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), kind text NOT NULL, status text NOT NULL DEFAULT 'pending', input jsonb NOT NULL, result jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS reference_entry_ordinal ON reference_entries(workspace_id,import_id,ordinal);
CREATE TABLE IF NOT EXISTS runs (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, document_version_id uuid NOT NULL, idempotency_key text NOT NULL, request_hash text NOT NULL, input jsonb NOT NULL, status text NOT NULL DEFAULT 'queued', stage text NOT NULL DEFAULT 'claims', cancel_requested boolean NOT NULL DEFAULT false, coverage jsonb NOT NULL DEFAULT '{}', config jsonb NOT NULL, error text, invalidated boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(workspace_id,idempotency_key), FOREIGN KEY(workspace_id,document_version_id) REFERENCES document_versions(workspace_id,id));
CREATE TABLE IF NOT EXISTS claims (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, run_id uuid NOT NULL, ordinal integer NOT NULL, data jsonb NOT NULL, UNIQUE(workspace_id,id), UNIQUE(run_id,ordinal), FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS citation_links (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, claim_id uuid NOT NULL, data jsonb NOT NULL, FOREIGN KEY(workspace_id,claim_id) REFERENCES claims(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS assessments (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, run_id uuid NOT NULL, claim_id uuid NOT NULL, cache_key text NOT NULL, input_passage_ids jsonb NOT NULL, data jsonb NOT NULL, UNIQUE(run_id,cache_key), FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id) ON DELETE CASCADE, FOREIGN KEY(workspace_id,claim_id) REFERENCES claims(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS findings (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, run_id uuid NOT NULL, claim_id uuid NOT NULL, ordinal integer NOT NULL, data jsonb NOT NULL, UNIQUE(run_id,claim_id), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id) ON DELETE CASCADE, FOREIGN KEY(workspace_id,claim_id) REFERENCES claims(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS evidence_links (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, finding_id uuid NOT NULL, passage_id uuid NOT NULL, data jsonb NOT NULL, FOREIGN KEY(workspace_id,finding_id) REFERENCES findings(workspace_id,id) ON DELETE CASCADE, FOREIGN KEY(workspace_id,passage_id) REFERENCES source_passages(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS run_events (sequence bigserial PRIMARY KEY, workspace_id uuid NOT NULL, run_id uuid NOT NULL, type text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS provider_calls (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, run_id uuid NOT NULL, provider text NOT NULL, operation text NOT NULL, status text NOT NULL DEFAULT 'unknown', usage jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS research_results (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, run_id uuid NOT NULL, query_key text NOT NULL, data jsonb NOT NULL, UNIQUE(run_id,query_key), FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS job_outbox (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, kind text NOT NULL, target_id uuid NOT NULL, delivered_at timestamptz, UNIQUE(kind,target_id));
CREATE TABLE IF NOT EXISTS deletion_jobs (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, object_keys jsonb NOT NULL, status text NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS compatibility_jobs (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), kind text NOT NULL, input jsonb NOT NULL, status text NOT NULL DEFAULT 'queued', progress text NOT NULL DEFAULT 'Queued', result jsonb NOT NULL DEFAULT '{}', run_id uuid, error text, idempotency_key text, request_hash text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(workspace_id,idempotency_key), FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id) ON DELETE CASCADE);

CREATE TABLE IF NOT EXISTS asset_provider_calls (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, asset_id uuid NOT NULL, provider text NOT NULL, usage jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,asset_id) REFERENCES source_assets(workspace_id,id) ON DELETE CASCADE);
